#include <queue>
#include <tuple>
#include <utility>
#include <vector>

using Point = std::pair<int, int>;

std::vector<Point> kClosest(const std::vector<Point>& points, int k) {
    // The k closest points so far as (squared distance, x, y), the farthest on top.
    std::priority_queue<std::tuple<int, int, int>> heap;
    for (const auto& [x, y] : points) {
        heap.emplace(x * x + y * y, x, y);
        if (static_cast<int>(heap.size()) > k) {
            heap.pop();
        }
    }
    std::vector<Point> closest;
    while (!heap.empty()) {
        auto [distance, x, y] = heap.top();
        heap.pop();
        closest.push_back({x, y});
    }
    std::reverse(closest.begin(), closest.end());
    return closest;
}

int main() {
    int n, k;
    std::cin >> n >> k;
    std::vector<Point> points(n);
    for (int i = 0; i < n; i++) {
        std::cin >> points[i].first >> points[i].second;
    }
    for (const Point& point : kClosest(points, k)) {
        std::cout << point.first << " " << point.second << "\n";
    }
    return 0;
}

