import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    static int[][] kClosest(int[][] points, int k) {
        // Closer first, then a smaller x, then a smaller y.
        Comparator<int[]> closerFirst = Comparator.comparingInt((int[] p) -> p[0] * p[0] + p[1] * p[1])
                .thenComparingInt(p -> p[0])
                .thenComparingInt(p -> p[1]);
        PriorityQueue<int[]> heap = new PriorityQueue<>(closerFirst.reversed()); // the farthest on top
        for (int[] point : points) {
            heap.offer(point);
            if (heap.size() > k) {
                heap.poll();
            }
        }
        int[][] closest = new int[heap.size()][];
        for (int i = closest.length - 1; i >= 0; i--) {
            closest[i] = heap.poll();
        }
        return closest;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int k = in.nextInt();
        int[][] points = new int[n][2];
        for (int i = 0; i < n; i++) {
            points[i][0] = in.nextInt();
            points[i][1] = in.nextInt();
        }
        for (int[] point : kClosest(points, k)) {
            System.out.println(point[0] + " " + point[1]);
        }
    }
}

