package main

import (
	"container/heap"
	"fmt"
)

type point struct {
	x, y int
}

func (p point) dist() int { return p.x*p.x + p.y*p.y }

// pointHeap implements heap.Interface with the farthest point on top: the
// biggest squared distance, then the biggest x, then the biggest y.
type pointHeap []point

func (h pointHeap) Len() int { return len(h) }
func (h pointHeap) Less(i, j int) bool {
	a, b := h[i], h[j]
	if a.dist() != b.dist() {
		return a.dist() > b.dist()
	}
	if a.x != b.x {
		return a.x > b.x
	}
	return a.y > b.y
}
func (h pointHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *pointHeap) Push(x interface{}) { *h = append(*h, x.(point)) }
func (h *pointHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func kClosest(points []point, k int) []point {
	h := &pointHeap{} // the k closest points so far, the farthest on top
	for _, p := range points {
		heap.Push(h, p)
		if h.Len() > k {
			heap.Pop(h)
		}
	}
	closest := make([]point, h.Len())
	for i := len(closest) - 1; i >= 0; i-- {
		closest[i] = heap.Pop(h).(point)
	}
	return closest
}

func main() {
	var n, k int
	fmt.Scan(&n, &k)
	points := make([]point, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&points[i].x, &points[i].y)
	}
	for _, p := range kClosest(points, k) {
		fmt.Println(p.x, p.y)
	}
}

